// Tracked repositories come from the repository itself, never from n8n state.
// PORTFOLIO_REPO_ROOT must point at a local checkout of the portfolio repo.
const fs = require('fs');
const path = require('path');
const repoRoot = $env.PORTFOLIO_REPO_ROOT;
if (!repoRoot) throw new Error('PORTFOLIO_REPO_ROOT is not configured on this n8n instance.');
const sources = JSON.parse(fs.readFileSync(path.join(repoRoot, 'automation', 'project-sources.json'), 'utf8'));
return Object.entries(sources.projects)
  .filter(([, source]) => source.enabled === true)
  .map(([slug, source]) => ({ json: { project_slug: slug, repository: source.repository } }));

// Deterministic meaningful-event filter. No model call happens before this gate.
// Eligible in V1: published releases, and merged PRs labelled 'portfolio-update'.
const LABEL = 'portfolio-update';
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  if (e.tag_name && e.draft !== true) {
    out.push({ json: { project_slug: e.project_slug, repository: e.repository, event_type: 'release', action: 'published', release: e, collected_at: new Date().toISOString() } });
    continue;
  }
  const labels = (e.labels || []).map((l) => String(l.name || l).toLowerCase());
  if (e.merged_at && labels.includes(LABEL)) {
    out.push({ json: { project_slug: e.project_slug, repository: e.repository, event_type: 'pull_request', action: 'closed', pull_request: { ...e, merged: true }, collected_at: new Date().toISOString() } });
  }
}
return out;

// Idempotency. Identity is the deterministic event_key, never a timestamp.
// State lives in n8n workflow static data, never in data/portfolio/.
const fs = require('fs');
const evidence = JSON.parse(fs.readFileSync(`${$env.PORTFOLIO_WORK_DIR}/evidence.json`, 'utf8'));
const store = $getWorkflowStaticData('global');
store.processedEventKeys = store.processedEventKeys || [];
if (store.processedEventKeys.includes(evidence.event_key)) {
  return [];
}
store.processedEventKeys.push(evidence.event_key);
return [{ json: evidence }];

// Persist the RAW provider response. Nothing downstream may read the model's
// output except through the parser: raw text is never handed to patch logic.
const fs = require('fs');
fs.writeFileSync(`${$env.PORTFOLIO_WORK_DIR}/gemini-response.json`, JSON.stringify($json), 'utf8');
return [{ json: { written: true } }];

// Load the human-approved proposal + approval artifact from the review directory.
// The approval artifact is produced by scripts/approve-portfolio-proposal.mjs and is
// never generated by the model. A missing artifact stops the run here.
const fs = require('fs');
const dir = $env.PORTFOLIO_WORK_DIR;
if (!fs.existsSync(`${dir}/approval.json`)) return [];
return [{ json: { approved: true } }];

// Draft PR creation is intentionally DISABLED in this template.
// Enable only after PORTFOLIO_GITHUB_WRITE_ENABLED=true and a write-scoped
// GitHub credential are configured, and after a human has reviewed the plan.
if ($env.PORTFOLIO_GITHUB_WRITE_ENABLED !== 'true') {
  return [{ json: { status: 'USER_CONFIG_REQUIRED', pr_created: false, plan: $json.stdout } }];
}
return [{ json: { status: 'READY', pr_created: false, plan: $json.stdout } }];
